def tr2():
    SM=R("submitted_model_eval.csv"); rows=[[r.farm,fi(r.cowdays),fi(r.cases),f"{100*r['random@5']:.1f}",f"{100*r['submitted model@5']:.1f}",f"{100*r['daily-sum deviation@5']:.1f}",f"{100*r['session-aware deviation@5']:.1f}",f"{10*r['onset lift: submitted']:.1f}",f"{10*r['onset lift: deviation rule']:.1f}"] for _,r in SM.sort_values("farm").iterrows()]
    m=SM.mean(numeric_only=True); rows.append(["Mean","","",f"{100*m['random@5']:.1f}",f"{100*m['submitted model@5']:.1f}",f"{100*m['daily-sum deviation@5']:.1f}",f"{100*m['session-aware deviation@5']:.1f}",f"{10*m['onset lift: submitted']:.1f}",f"{10*m['onset lift: deviation rule']:.1f}"])
    ends=sorted(set(p.split("..")[1] for p in SM.period)); starts=sorted(set(p.split("..")[0] for p in SM.period)); assert starts==["2024-05-04","2025-03-31"] and ends==["2024-09-18","2025-09-26","2025-09-27"], (starts,ends)
    return table(["Farm","Cow-days","Disease cases","Cases detected by 5% lists, %: random lists (one draw)","Previous model","Deviation of the daily sum","Deviation rule","Next-day acute drops on 10% lists, %: previous model","Deviation rule"],rows,widths=[8,10,10,12,11,13,12,12,12],caption="Table R2. The model of the previous version evaluated on the cow-days of its own test folds against veterinary disease records and next-day acute drops; all scores are ranked within the same cows.",note="The test folds of the previous version ran from 31 March to 26 or 27 September 2025 (Farm 6: 4 May to 18 September 2024). Cow-days and cases are those of these folds that were in the Task 2 risk set (Table R1 counts all cow-days of the folds); the last two columns refer to the cow-days of the same folds in the Task 1 risk set. Predictions of the previous model for day t + 1 were used as its score at the end of day t. Farm 7 was not part of the previous test folds.")
def tr1():
    SL=R("tab1_submitted_label_by_farm.csv").set_index("farm_label"); SC=R("tab_submitted_label_scores.csv").set_index("score"); rows=[]
    for f in [x for x in FARMS if x in SL.index]:
        r=SL.loc[f]; rows.append([f,fi(r.n),p1(r.prev),p1(r.events_on_incomplete),f"{p1(r.rate_incomplete)} / {p1(r.rate_complete)}",f"{10*SC.loc['previous-day ratio',f]:.1f}",f"{10*SC.loc['submitted model',f]:.1f}"])
    rows.append(["All test folds","3,328,285","9.2","49.4","30.4 / 5.4",f"{10*SC.loc['previous-day ratio','lift10']:.1f}",f"{10*SC.loc['submitted model','lift10']:.1f}"])
    return table(["Farm","Cow-days in the previous test fold","Labelled as anomaly, %","Labelled cow-days with fewer recorded milkings than usual on the farm-day, %","Label rate: such cow-days / others, %","Next-day labels on 10% lists ranked by the yield ratio of the current day, %","Ranked by the previously submitted model, %"],rows,caption="Table R1. The anomaly label of the previous version on its test folds: share lying on cow-days with incomplete milking records, and share of next-day labels placed on daily lists of 10% of cows by the previous day's yield ratio alone and by the previously submitted model.")
